<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Page Not Found — IdeaForum</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: #FFFFFF;
  color: #121212;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  -webkit-font-smoothing: antialiased;
}

.page-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 620px;
  padding: 60px 24px 100px;
}

/* Logo */
.logo {
  margin-bottom: 56px;
  text-align: center;
}

.logo svg {
  height: 48px;
  width: auto;
}

/* Error message */
.error-message {
  text-align: center;
  margin-bottom: 12px;
}

.error-message h1 {
  font-size: 1.75rem;
  font-weight: 600;
  color: #121212;
  letter-spacing: -0.01em;
}

.error-suggestion {
  text-align: center;
  color: #555;
  font-size: 0.95rem;
  line-height: 1.6;
  margin-bottom: 28px;
}

/* Search */
.search-wrapper {
  width: 100%;
  position: relative;
  margin-bottom: 32px;
}

.search-wrapper input {
  width: 100%;
  padding: 14px 52px 14px 18px;
  font-size: 0.95rem;
  font-family: inherit;
  border: 1.5px solid #D0D0D0;
  border-radius: 8px;
  outline: none;
  background: #FFFFFF;
  color: #121212;
  transition: border-color 0.2s;
}

.search-wrapper input::placeholder {
  color: #999;
}

.search-wrapper input:focus {
  border-color: #EB0028;
}

.search-btn {
  position: absolute;
  right: 6px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #777;
  transition: color 0.2s;
}

.search-btn:hover {
  color: #EB0028;
}

.search-btn svg {
  width: 20px;
  height: 20px;
}

/* Error code bar */
.error-code-bar {
  width: 100%;
  background: #F5F5F5;
  padding: 12px 18px;
  border-radius: 6px;
  margin-bottom: 24px;
}

.error-code-bar span {
  font-size: 0.8rem;
  font-weight: 500;
  color: #888;
  letter-spacing: 0.04em;
}

.divider {
  width: 100%;
  height: 1px;
  background: #E5E5E5;
  margin-bottom: 28px;
}

/* Next steps */
.next-steps h2 {
  font-size: 1.05rem;
  font-weight: 600;
  color: #121212;
  margin-bottom: 14px;
}

.next-steps ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.next-steps a {
  color: #777;
  text-decoration: none;
  font-size: 0.95rem;
  transition: color 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.next-steps a:hover {
  color: #EB0028;
  text-decoration: underline;
}

.next-steps a::after {
  content: '\2192';
  font-size: 0.85em;
}

/* Cookie banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: #1A1A1A;
  color: #D0D0D0;
  padding: 20px 24px;
  font-size: 0.82rem;
  line-height: 1.65;
  z-index: 100;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
  transform: translateY(0);
  transition: transform 0.35s ease;
}

.cookie-banner.hidden {
  transform: translateY(100%);
  pointer-events: none;
}

.cookie-banner p {
  max-width: 640px;
}

.cookie-banner a {
  color: #FFFFFF;
  text-decoration: underline;
}

.cookie-banner a:hover {
  color: #EB0028;
}

.cookie-btn {
  background: #FFFFFF;
  color: #121212;
  border: none;
  padding: 10px 22px;
  font-size: 0.82rem;
  font-family: inherit;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.2s;
}

.cookie-btn:hover {
  background: #F0F0F0;
}

/* Cookie preferences modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.45);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s;
}

.modal-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.modal {
  background: #FFFFFF;
  border-radius: 12px;
  width: 90%;
  max-width: 480px;
  padding: 32px;
  box-shadow: 0 16px 48px rgba(0,0,0,0.15);
}

.modal h3 {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 20px;
  color: #121212;
}

.pref-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid #ECECEC;
}

.pref-row:last-of-type {
  border-bottom: none;
}

.pref-label span {
  display: block;
  font-size: 0.9rem;
  font-weight: 500;
  color: #121212;
}

.pref-label small {
  color: #888;
  font-size: 0.78rem;
}

/* Toggle switch */
.toggle {
  position: relative;
  width: 44px;
  height: 24px;
  flex-shrink: 0;
}

.toggle input {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle .slider {
  position: absolute;
  inset: 0;
  background: #CCC;
  border-radius: 24px;
  cursor: pointer;
  transition: background 0.2s;
}

.toggle .slider::before {
  content: '';
  position: absolute;
  width: 18px;
  height: 18px;
  left: 3px;
  bottom: 3px;
  background: #FFF;
  border-radius: 50%;
  transition: transform 0.2s;
}

.toggle input:checked + .slider {
  background: #EB0028;
}

.toggle input:checked + .slider::before {
  transform: translateX(20px);
}

.toggle input:disabled + .slider {
  opacity: 0.6;
  cursor: default;
}

.modal-actions {
  display: flex;
  gap: 12px;
  margin-top: 24px;
  justify-content: flex-end;
}

.btn-save {
  background: #EB0028;
  color: #FFF;
  border: none;
  padding: 10px 24px;
  font-size: 0.85rem;
  font-family: inherit;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.2s;
}

.btn-save:hover {
  background: #C70022;
}

.btn-cancel {
  background: none;
  border: 1.5px solid #D0D0D0;
  padding: 10px 20px;
  font-size: 0.85rem;
  font-family: inherit;
  font-weight: 500;
  border-radius: 6px;
  cursor: pointer;
  color: #555;
  transition: border-color 0.2s;
}

.btn-cancel:hover {
  border-color: #999;
}

/* Responsive */
@media (max-width: 600px) {
  .page-wrapper {
    padding: 40px 20px 120px;
  }

  .logo svg {
    height: 38px;
  }

  .error-message h1 {
    font-size: 1.45rem;
  }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    padding: 18px 20px;
    gap: 12px;
  }

  .modal {
    padding: 24px;
    width: 94%;
  }
}
</style>
</head>
<body>

<div class="page-wrapper">
  <!-- Logo -->
  <div class="logo" aria-label="IdeaForum">
    <svg viewBox="0 0 360 48" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="IdeaForum logo">
      <text x="0" y="38" font-family="Inter, sans-serif" font-weight="700" font-size="42" fill="#EB0028" letter-spacing="-1">Id</text>
      <!-- Missing E as dashed outline -->
      <text x="55" y="38" font-family="Inter, sans-serif" font-weight="700" font-size="42" fill="none" stroke="#EB0028" stroke-width="1.2" stroke-dasharray="4,3" letter-spacing="-1">e</text>
      <text x="80" y="38" font-family="Inter, sans-serif" font-weight="700" font-size="42" fill="#EB0028" letter-spacing="-1">aForum</text>
    </svg>
  </div>

  <!-- Error message -->
  <div class="error-message">
    <h1>Sorry, we can't find that.</h1>
  </div>
  <p class="error-suggestion">Perhaps we can help you find the content you're looking for:</p>

  <!-- Search -->
  <form class="search-wrapper" role="search" onsubmit="handleSearch(event)">
    <input type="text" id="searchInput" placeholder="Search IdeaForum..." aria-label="Search IdeaForum">
    <button type="submit" class="search-btn" aria-label="Search">
      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><line x1="16.5" y1="16.5" x2="21" y2="21"/></svg>
    </button>
  </form>

  <!-- Error code -->
  <div class="error-code-bar">
    <span>HTTP Error 404</span>
  </div>

  <div class="divider"></div>

  <!-- Next steps -->
  <nav class="next-steps">
    <h2>What's next?</h2>
    <ul>
      <li><a href="/">Go to the homepage</a></li>
      <li><a href="/help">Visit our Help Desk</a></li>
    </ul>
  </nav>
</div>

<!-- Cookie consent banner -->
<div class="cookie-banner" id="cookieBanner">
  <p>This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link: <a href="/privacy" target="_blank" rel="noopener">Privacy Policy</a></p>
  <button class="cookie-btn" onclick="openPrefs()">Manage Preferences</button>
</div>

<!-- Cookie preferences modal -->
<div class="modal-overlay" id="prefsOverlay" onclick="closePrefs(event)">
  <div class="modal" onclick="event.stopPropagation()">
    <h3>Cookie Preferences</h3>

    <div class="pref-row">
      <div class="pref-label">
        <span>Essential</span>
        <small>Required for site functionality</small>
      </div>
      <label class="toggle">
        <input type="checkbox" checked disabled>
        <span class="slider"></span>
      </label>
    </div>

    <div class="pref-row">
      <div class="pref-label">
        <span>Analytics</span>
        <small>Help us improve our site</small>
      </div>
      <label class="toggle">
        <input type="checkbox" id="prefAnalytics">
        <span class="slider"></span>
      </label>
    </div>

    <div class="pref-row">
      <div class="pref-label">
        <span>Personalization</span>
        <small>Tailor content to your interests</small>
      </div>
      <label class="toggle">
        <input type="checkbox" id="prefPersonal">
        <span class="slider"></span>
      </label>
    </div>

    <div class="pref-row">
      <div class="pref-label">
        <span>Advertising</span>
        <small>Relevant ads and campaigns</small>
      </div>
      <label class="toggle">
        <input type="checkbox" id="prefAds">
        <span class="slider"></span>
      </label>
    </div>

    <div class="modal-actions">
      <button class="btn-cancel" onclick="closePrefs()">Cancel</button>
      <button class="btn-save" onclick="savePrefs()">Save Preferences</button>
    </div>
  </div>
</div>

<script>
function handleSearch(e) {
  e.preventDefault();
  var q = document.getElementById('searchInput').value.trim();
  if (q) window.location.href = '/search?q=' + encodeURIComponent(q);
}

function openPrefs() {
  document.getElementById('prefsOverlay').classList.add('active');
}

function closePrefs(e) {
  if (!e || e.target === document.getElementById('prefsOverlay')) {
    document.getElementById('prefsOverlay').classList.remove('active');
  }
}

function savePrefs() {
  document.getElementById('cookieBanner').classList.add('hidden');
  document.getElementById('prefsOverlay').classList.remove('active');
}

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') closePrefs();
});
</script>

</body>
</html>
